CREATE TABLE user_profiles (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL DEFAULT '', age INTEGER, height_cm NUMERIC(6,2), current_weight_kg NUMERIC(6,2), target_weight_kg NUMERIC(6,2), activity_level TEXT NOT NULL DEFAULT 'moderate', goal TEXT NOT NULL DEFAULT 'maintain', diet TEXT NOT NULL DEFAULT 'vegetarian', units TEXT NOT NULL DEFAULT 'metric', calorie_target INTEGER NOT NULL DEFAULT 2000, protein_target NUMERIC(7,2) NOT NULL DEFAULT 100, carbs_target NUMERIC(7,2) NOT NULL DEFAULT 250, fat_target NUMERIC(7,2) NOT NULL DEFAULT 65, water_target_ml INTEGER NOT NULL DEFAULT 2000, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE foods (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'General', diet_type TEXT NOT NULL DEFAULT 'vegetarian', serving_label TEXT NOT NULL DEFAULT '100 g', serving_grams NUMERIC(8,2) NOT NULL DEFAULT 100, calories NUMERIC(8,2) NOT NULL DEFAULT 0, protein NUMERIC(8,2) NOT NULL DEFAULT 0, carbs NUMERIC(8,2) NOT NULL DEFAULT 0, fat NUMERIC(8,2) NOT NULL DEFAULT 0, fiber NUMERIC(8,2) NOT NULL DEFAULT 0, source_label TEXT NOT NULL DEFAULT 'Illustrative estimate', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX foods_name_idx ON foods(name);
CREATE TABLE food_diary_entries (id BIGSERIAL PRIMARY KEY, user_id TEXT NOT NULL, food_id BIGINT REFERENCES foods(id), custom_name TEXT, entry_date DATE NOT NULL, meal_type TEXT NOT NULL CHECK (meal_type IN ('Breakfast','Lunch','Dinner','Snacks')), quantity NUMERIC(8,2) NOT NULL CHECK (quantity > 0), calories NUMERIC(10,2) NOT NULL DEFAULT 0, protein NUMERIC(10,2) NOT NULL DEFAULT 0, carbs NUMERIC(10,2) NOT NULL DEFAULT 0, fat NUMERIC(10,2) NOT NULL DEFAULT 0, fiber NUMERIC(10,2) NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX diary_user_date_idx ON food_diary_entries(user_id, entry_date);
CREATE TABLE weight_entries (id BIGSERIAL PRIMARY KEY, user_id TEXT NOT NULL, weight_kg NUMERIC(6,2) NOT NULL CHECK (weight_kg > 0 AND weight_kg < 700), entry_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, entry_date));
CREATE TABLE water_entries (id BIGSERIAL PRIMARY KEY, user_id TEXT NOT NULL, amount_ml INTEGER NOT NULL CHECK (amount_ml > 0 AND amount_ml <= 5000), entry_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX water_user_date_idx ON water_entries(user_id, entry_date);